@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">Welcome to the University Course Catalog</h1>
    <p class="lead">Explore our diverse range of courses and find the perfect fit for your academic journey.</p>
    <a href="courses" class="btn btn-primary btn-lg mt-2">Browse All Courses</a>
</div>

<h2 class="mb-3">Featured Courses</h2>
<div class="row row-cols-1 row-cols-md-3 g-4 mb-5">
    @foreach (var course in featuredCourses)
    {
        var dept = departments.FirstOrDefault(d => d.Id == course.DepartmentId);
        <div class="col">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@course.Title</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@course.Code</h6>
                    <p class="card-text">
                        <span class="badge bg-secondary">@course.Credits Credits</span>
                        <span class="badge bg-info">@dept?.Name</span>
                    </p>
                </div>
                <div class="card-footer">
                    <a href="courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mb-3">Browse by Department</h2>
<div class="list-group">
    @foreach (var dept in departments)
    {
        <a href="courses?DepartmentId=@dept.Id" class="list-group-item list-group-item-action">
            <strong>@dept.Name</strong> — @dept.Description
        </a>
    }
</div>

@code {
    private List<Course> featuredCourses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" class="form-control" id="search" name="Search" value="@Search" placeholder="Search by title, code, or description..." />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select class="form-select" id="departmentId" name="DepartmentId">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                if (DepartmentId.HasValue && DepartmentId.Value == dept.Id)
                {
                    <option value="@dept.Id" selected>@dept.Name</option>
                }
                else
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (courses.Any())
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Credits</th>
                <th>Department</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                var dept = departments.FirstOrDefault(d => d.Id == course.DepartmentId);
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@course.Credits</td>
                    <td>@dept?.Name</td>
                    <td>@course.Schedule</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}
else
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private List<Course> courses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.GetCourses(Search, DepartmentId);
    }
}

