@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>

@if (!string.IsNullOrEmpty(confirmationMessage))
{
    <div class="alert alert-success mt-3">
        <h4 class="alert-heading">Success!</h4>
        <p>@confirmationMessage</p>
        <hr />
        <a href="courses" class="btn btn-primary">Browse More Courses</a>
        <a href="enroll" class="btn btn-outline-secondary ms-2">Submit Another Request</a>
    </div>
}
else
{
    <p>Fill out the form below to submit an enrollment request.</p>

    <EditForm Model="Model" method="post" OnValidSubmit="HandleSubmit" FormName="enrollment" class="mt-3">
        <AntiforgeryToken />
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="studentName" class="form-label">Student Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="Model!.StudentName" />
            <ValidationMessage For="() => Model!.StudentName" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="Model!.StudentId" />
            <ValidationMessage For="() => Model!.StudentId" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" class="form-select" @bind-Value="Model!.CourseId">
                <option value="0">-- Select a Course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id">@course.Code - @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model!.CourseId" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest? Model { get; set; }

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<Course> courses = new();
    private string? confirmationMessage;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses(null, null);
        Model ??= new EnrollmentRequest();

        if (CourseId.HasValue && CourseId.Value > 0 && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        confirmationMessage = CatalogService.SubmitEnrollmentRequest(Model!);
    }
}

